  1937→static void test_compute_vanishing_polynomial_from_roots(void) {
  1938→    /*
  1939→     * Test case: (x - 2)(x - 3)
  1940→     *
  1941→     * Expected result: x^2 - 5x + 6
  1942→     */
  1943→
  1944→    /* Initialize array with the roots 2 and 3 */
  1945→    fr_t roots[2];
  1946→    fr_from_uint64(&roots[0], 2);
  1947→    fr_from_uint64(&roots[1], 3);
  1948→    size_t roots_len = 2;
  1949→
  1950→    fr_t poly[3];
  1951→    size_t poly_len = 3;
  1952→
  1953→    compute_vanishing_polynomial_from_roots(poly, &poly_len, roots, roots_len);
  1954→
  1955→    fr_t expected[3];
  1956→
  1957→    fr_from_uint64(&expected[0], 6);
  1958→
  1959→    /* Negate 5 */
  1960→    fr_from_uint64(&expected[1], 5);
  1961→    blst_fr_cneg(&expected[1], &expected[1], true);
  1962→
  1963→    expected[2] = FR_ONE;
  1964→
  1965→    ASSERT("polynomial length is 3", poly_len == 3);
  1966→    ASSERT("coefficient 0 are equal", fr_equal(&poly[0], &expected[0]));
  1967→    ASSERT("coefficient 1 are equal", fr_equal(&poly[1], &expected[1]));
  1968→    ASSERT("coefficient 2 are equal", fr_equal(&poly[2], &expected[2]));
  1969→}
  1970→
  1971→static void test_vanishing_polynomial_for_missing_cells(void) {
  1972→    C_KZG_RET ret;
  1973→
  1974→    fr_t vanishing_poly[FIELD_ELEMENTS_PER_EXT_BLOB];
  1975→    fr_t fft_result[FIELD_ELEMENTS_PER_EXT_BLOB];
  1976→
  1977→    /* Test case: the 0th and 1st cell are missing */
  1978→    uint64_t missing_cell_indices[] = {0, 1};
  1979→    size_t len_missing_cells = 2;
  1980→
  1981→    ret = vanishing_polynomial_for_missing_cells(
  1982→        vanishing_poly, missing_cell_indices, len_missing_cells, &s
  1983→    );
  1984→
  1985→    /* Check return status */
  1986→    ASSERT("compute vanishing poly from cells", ret == C_KZG_OK);
  1987→
  1988→    /* Compute FFT of vanishing_poly */
  1989→    fr_fft(fft_result, vanishing_poly, FIELD_ELEMENTS_PER_EXT_BLOB, &s);
  1990→
  1991→    /*
  1992→     * Check FFT results
  1993→     *
  1994→     * Let explain how we are picking the roots of unity:
  1995→     * Focussing just on the missing cell index 0.
  1996→     *
  1997→     * We expect that the following roots will evaluate to zero on the vanishing polynomial we
  1998→     * computed:
  1999→     *
  2000→     * s->roots_of_unity[0]
  2001→     * s->roots_of_unity[128]
  2002→     * s->roots_of_unity[256]
  2003→     * ...
